#!/usr/bin/env python3
"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr.

Reads exactly one JSON campaign document on stdin and writes exactly one JSON
certificate on stdout.  Framing failures (duplicate keys, nonfinite numbers,
invalid UTF-8, malformed or trailing JSON, oversized input) produce exactly
``{"error":"INVALID_INPUT"}``.  Exit status is always zero.
"""
import json
import math
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))
sys.setrecursionlimit(20000)

from eywa.offline import execute  # noqa: E402  (needs the local src on the path)

CAP = 64 * 1024 * 1024


def pairs(items):
    d = {}
    for key, value in items:
        if key in d:
            raise ValueError("duplicate key")
        d[key] = value
    return d


def read_request():
    raw = sys.stdin.buffer.read(CAP + 1)
    if len(raw) > CAP:
        raise ValueError("input cap")

    def bad(value):
        raise ValueError("nonfinite")

    def finite(value):
        result = float(value)
        if not math.isfinite(result):
            raise ValueError("nonfinite")
        return result

    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad, parse_float=finite)


def emit(result):
    text = json.dumps(result, ensure_ascii=True, separators=(",", ":"),
                      allow_nan=False)
    stream = sys.stdout
    stream.write(text)
    stream.write("\n")
    stream.flush()


def main():
    try:
        request = read_request()
    except (ValueError, UnicodeError, RecursionError, MemoryError):
        emit({"error": "INVALID_INPUT"})
        return
    try:
        result = execute(request)
    except Exception as exc:  # pragma: no cover - diagnostics only
        # A campaign that cannot be compiled still produces one JSON object.
        print("eywa: %s: %s" % (type(exc).__name__, exc), file=sys.stderr)
        result = {"error": "INVALID_INPUT"}
    emit(result)


if __name__ == "__main__":
    main()
PYEOF
